import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May inclusive


def request(method, path, token=None):
    """Return (status, headers, body_text). Retries transient failures and waits on 429."""
    attempts = 0
    while True:
        attempts += 1
        req = urllib.request.Request(BASE + path, method=method)
        if token:
            req.add_header("Authorization", "Bearer " + token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read().decode("utf-8")
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                try:
                    wait = float(wait)
                except (TypeError, ValueError):
                    wait = 5.0
                print(f"429 on {path}; waiting {wait}s. body={body[:200]}", file=sys.stderr)
                time.sleep(wait + 0.5)
                continue
            if e.code in (401, 403) and token is not None:
                return e.code, e.headers, body
            if e.code == 404:
                return e.code, e.headers, body
            print(f"HTTP {e.code} on {path} (attempt {attempts}): {body[:200]}", file=sys.stderr)
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            print(f"transport error on {path} (attempt {attempts}): {e}", file=sys.stderr)
        if attempts > 50:
            raise RuntimeError(f"giving up on {path}")
        time.sleep(min(2 ** attempts, 30))


class Client:
    def __init__(self):
        self.token = None
        self.refresh()

    def refresh(self):
        status, _, body = request("POST", "/token")
        self.token = json.loads(body)["token"]

    def get_json(self, path):
        while True:
            status, headers, body = request("GET", path, self.token)
            if status == 401:
                print(f"401 on {path}; refreshing token", file=sys.stderr)
                self.refresh()
                continue
            if status == 404:
                return None
            if status == 200:
                try:
                    return json.loads(body)
                except json.JSONDecodeError:
                    print(f"bad JSON on {path}: {body[:200]}", file=sys.stderr)
                    time.sleep(2)
                    continue
            print(f"status {status} on {path}: {body[:200]}", file=sys.stderr)
            time.sleep(2)


def main():
    client = Client()
    seen = {}
    duplicates = 0
    pages_fetched = []

    # Walk pages by following "next" rather than trusting total_pages.
    path = "/orders?page=1"
    while path:
        page = client.get_json(path)
        if page is None:
            raise RuntimeError(f"unexpected 404 for {path}")
        pages_fetched.append(page.get("page"))
        for item in page["items"]:
            oid = item["id"]
            if oid in seen:
                duplicates += 1
                if seen[oid] != item:
                    print(f"WARNING: duplicate id {oid} with differing content", file=sys.stderr)
                continue
            seen[oid] = item
        path = page.get("next")

    print(f"pages fetched: {len(pages_fetched)} (total_pages field last seen: {page.get('total_pages')})",
          file=sys.stderr)
    print(f"distinct orders: {len(seen)}; duplicate listings discarded: {duplicates}", file=sys.stderr)

    customers = {}
    total = 0
    count = 0
    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    status_counts = {}
    odd_timestamps = 0
    skipped_in_range_no_customer = 0

    for oid, o in seen.items():
        status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
        if o["status"] != "shipped":
            continue
        ts = datetime.fromisoformat(o["placed_at"].replace("Z", "+00:00"))
        if ts.tzinfo is None:
            odd_timestamps += 1
            ts = ts.replace(tzinfo=timezone.utc)
        ts = ts.astimezone(timezone.utc)
        if not (START <= ts < END):
            continue

        cid = o["customer_id"]
        if cid not in customers:
            cust = client.get_json(f"/customers/{cid}")
            if cust is None:
                raise RuntimeError(f"customer {cid} not found for order {oid}")
            customers[cid] = cust
        cust = customers[cid]

        amount = int(o["amount_cents"])
        pct = int(cust["discount_pct"])
        # discounted = amount * (100 - pct) / 100, rounded half up per order, all integer math.
        num = amount * (100 - pct)
        discounted = (num + 50) // 100

        total += discounted
        count += 1
        if cust["region"] not in by_region:
            raise RuntimeError(f"unknown region {cust['region']} for {cid}")
        by_region[cust["region"]] += discounted

    print(f"status counts (all distinct orders): {status_counts}", file=sys.stderr)
    print(f"naive-timestamp orders encountered: {odd_timestamps}", file=sys.stderr)
    print(f"customers looked up: {len(customers)}", file=sys.stderr)

    assert sum(by_region.values()) == total

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

